exercises.solution:
def count_pairs(events):
    counts = {}
    for pair in events:
        counts[pair] = counts.get(pair, 0) + 1
    return counts

def unique_points(points):
    seen = set()
    result = []
    for p in points:
        key = tuple(p)
        if key not in seen:
            seen.add(key)
            result.append(key)
    return result

